import{_ as n,o as i,c as r,ae as t}from"./chunks/framework.BvHJbMD4.js";const g=JSON.parse('{"title":"Teil 1: Die schillernde Witwe","description":"","frontmatter":{},"headers":[],"relativePath":"drehbuch/teil-1-die-schillernde-witwe.md","filePath":"drehbuch/teil-1-die-schillernde-witwe.md"}'),s={name:"drehbuch/teil-1-die-schillernde-witwe.md"};function a(h,e,d,l,o,c){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="teil-1-die-schillernde-witwe" tabindex="-1">Teil 1: Die schillernde Witwe <a class="header-anchor" href="#teil-1-die-schillernde-witwe" aria-label="Permalink to &quot;Teil 1: Die schillernde Witwe&quot;">​</a></h1><p><strong>Arbeitstitel:</strong> <em>Vom Glanz der Stille</em></p><p><strong>Besetzung:</strong> Birgit Minichmayr (Heidi Horten), August Diehl (Der junge Helmut - in Rückblenden), Oliver Masucci (Der Kurator/Chronist).</p><hr><h2 id="szene-1-das-archiv-des-lachelns" tabindex="-1">Szene 1: Das Archiv des Lächelns <a class="header-anchor" href="#szene-1-das-archiv-des-lachelns" aria-label="Permalink to &quot;Szene 1: Das Archiv des Lächelns&quot;">​</a></h2><p><strong>Ort:</strong> Ein hochmodernes, klimatisiertes Depot in der Nähe von Klagenfurt. <strong>Zeit:</strong> Gegenwart.</p><p>Überall stehen weiße Handschuhe auf polierten Tischen. Die Kamera gleitet über endlose Reihen von Schmuckschatullen. Heidi (Birgit Minichmayr) tritt ins Bild. Sie trägt ein schlichtes, aber unbezahlbares Seidenkleid. Sie öffnet eine Schatulle nach der anderen.</p><p><strong>HEIDI</strong> (leise, fast zärtlich) Das ist nicht nur Schmuck. Das sind konservierte Momente. Helmut sagte immer: „Heidi, Gold weint nicht.“ Er hatte recht. Es glänzt einfach weiter, egal was draußen passiert.</p><p>Sie nimmt ein Collier heraus, die Perlen schimmern im künstlichen Licht.</p><p><strong>HEIDI (Forts.)</strong> Sehen Sie diese Perle? Sie ist ein Punkt. Ein kleiner, weißer Punkt in einer unendlichen Bilanz. Wenn man genug davon hat, sieht man das Bild nicht mehr. Man sieht nur noch das Licht. Das ist mein Pointillismus.</p><hr><h2 id="szene-2-der-perlen-inventur-tango-neu" tabindex="-1">Szene 2: Der Perlen-Inventur-Tango (NEU) <a class="header-anchor" href="#szene-2-der-perlen-inventur-tango-neu" aria-label="Permalink to &quot;Szene 2: Der Perlen-Inventur-Tango (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Der große Spiegelsaal im Palais. <strong>Zeit:</strong> Eine schlaflose Nacht.</p><p>Heidi breitet tausende Perlen auf einem riesigen schwarzen Samttuch aus. Sie beginnt, sie mit einer silbernen Pinzette zu sortieren. Der Rhythmus ihrer Bewegungen wird fast tänzerisch. Im Hintergrund läuft leise eine verzerrte Version eines Walzers.</p><p><strong>HEIDI</strong> (zu einer imaginären Person) Eins für die Stiftung. Eins für die Kunst. Drei für das Schweigen. Und eins... für die Ewigkeit.</p><p>Der Kurator (Oliver Masucci) beobachtet sie aus dem Schatten.</p><p><strong>KURATOR</strong> Madame, die Liste der Spendenanfragen ist gewachsen. Die Politik klopft an. Sie wollen wieder... Regen.</p><p><strong>HEIDI</strong> (ohne aufzusehen) Dann geben wir ihnen Regen, Kurator. Aber nur in Tropfen. Stück für Stück. Wie diese Perlen. Wenn man alles auf einmal gibt, ertrinken sie. Wenn man es stückelt, wächst die Dankbarkeit.</p><hr><h2 id="szene-3-das-schweigen-der-jachten-neu" tabindex="-1">Szene 3: Das Schweigen der Jachten (NEU) <a class="header-anchor" href="#szene-3-das-schweigen-der-jachten-neu" aria-label="Permalink to &quot;Szene 3: Das Schweigen der Jachten (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Deck der <em>Carinthia VII</em>, vor der Küste von Nizza. <strong>Zeit:</strong> Sonnenuntergang.</p><p>Die Kamera zeigt die gewaltigen Ausmaße der Jacht. Es ist so still, dass man nur das sanfte Summen der Generatoren hört. Heidi sitzt am Heck und starrt auf das Kielwasser.</p><p><strong>HEIDI</strong> Helmut liebte das Meer. Er sagte, Wasser hat kein Gedächtnis. Man kann eine Spur ziehen, und Sekunden später ist sie weg. Das ist die Freiheit des Geldes. Es löscht die Spuren seiner eigenen Entstehung.</p><p>Ein Steward serviert Champagner in Kristallgläsern, die so dünn sind, dass sie beim bloßen Hinsehen zu brechen scheinen.</p><p><strong>HEIDI (Forts.)</strong> Wissen Sie, was das Problem mit der Geschichte ist? Sie ist zu laut. Sie staubt. Reichtum hingegen ist klinisch rein. Er riecht nach nichts. Außer nach dem Morgen.</p><hr><h2 id="szene-4-die-heidi-gala-–-die-inszenierung-des-nichts-neu" tabindex="-1">Szene 4: Die Heidi-Gala – Die Inszenierung des Nichts (NEU) <a class="header-anchor" href="#szene-4-die-heidi-gala-–-die-inszenierung-des-nichts-neu" aria-label="Permalink to &quot;Szene 4: Die Heidi-Gala – Die Inszenierung des Nichts (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein festlich geschmückter Saal, voller Blumen, die so gezüchtet wurden, dass sie genau drei Stunden halten. <strong>Zeit:</strong> Ein Abend der „höheren Gesellschaft“.</p><p>Birgit Minichmayr brilliert in einer Szene, in der sie hunderte Gäste begrüßt, ohne ein einziges echtes Wort zu sagen. Es ist eine Choreografie des Kopfnickens und der angedeuteten Umarmungen.</p><p><strong>ERZÄHLER (Masucci, Off-Stimme)</strong> Sie nannte es Wohltätigkeit. Die Presse nannte es Großzügigkeit. Wir nennen es die perfekte Ablenkung. Jedes gespendete Bild, jede geförderte Schule war ein Pinselstrich mehr in einem Porträt, das die Vergangenheit übermalte.</p><p>Heidi steht am Mikrofon. Der Saal wird still.</p><p><strong>HEIDI</strong> Wir sind hier, um das Schöne zu feiern. Denn das Schöne braucht keine Erklärung. Es ist einfach da. Wie das Erbe, das wir verwalten. Wir stellen nicht die Frage: „Woher?“ Wir stellen die Frage: „Wohin?“ Und die Antwort ist immer: In die Zukunft.</p><hr><h2 id="szene-5-das-archiv-der-leere" tabindex="-1">Szene 5: Das Archiv der Leere <a class="header-anchor" href="#szene-5-das-archiv-der-leere" aria-label="Permalink to &quot;Szene 5: Das Archiv der Leere&quot;">​</a></h2><p><strong>Ort:</strong> Ein kleiner, dunkler Raum hinter der Galerie. <strong>Zeit:</strong> Spät in der Nacht.</p><p>Heidi betrachtet ein altes Schwarz-Weiß-Foto von Helmut vor seinem ersten Kaufhaus. Ihr Gesichtsausdruck wechselt von Nostalgie zu einer kalten, fast maskenhaften Entschlossenheit.</p><p><strong>HEIDI</strong> (flüsternd zum Foto) Ich habe es sauber gehalten, Helmut. Keiner sieht mehr den Staub. Nur noch den Glanz.</p><p>Sie löscht das Licht. Nur das Collier in ihrer Hand leuchtet noch einen Moment lang nach, bevor alles schwarz wird.</p><hr><h2 id="szene-6-der-pointillismus-der-macht-neu" tabindex="-1">Szene 6: Der Pointillismus der Macht (NEU) <a class="header-anchor" href="#szene-6-der-pointillismus-der-macht-neu" aria-label="Permalink to &quot;Szene 6: Der Pointillismus der Macht (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein vertrauliches Gespräch im Wintergarten. <strong>Zeit:</strong> Ein kalter Januarmorgen.</p><p>Heidi trifft sich mit einem hohen Vertreter der „Freunde der Kunst“ (ein Codewort für politische Strippenzieher).</p><p><strong>REPRÄSENTANT</strong> Die Wahlen stehen an, Madame. Das Volk ist... unruhig. Sie stellen Fragen über die Herkunft der großen Vermögen.</p><p><strong>HEIDI</strong> Dann müssen wir die Punkte kleiner machen. Wenn man nah dran ist, sieht man nur das Chaos. Wenn man weit weg geht, sieht man ein Meisterwerk. Wir müssen dafür sorgen, dass alle weit genug weg stehen.</p><p>Sie schüttet einen Beutel winziger Diamanten auf den Tisch. Sie funkeln wie Sterne.</p><p><strong>HEIDI (Forts.)</strong> Hier. Das ist mein Beitrag zur politischen Stabilität. Verteilen Sie sie gut. Aber nennen Sie es niemals „Geld“. Nennen Sie es „Vision“.</p><hr><h2 id="szene-7-die-schatten-der-carinthia-neu" tabindex="-1">Szene 7: Die Schatten der <em>Carinthia</em> (NEU) <a class="header-anchor" href="#szene-7-die-schatten-der-carinthia-neu" aria-label="Permalink to &quot;Szene 7: Die Schatten der *Carinthia* (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Im Bauch der Jacht, bei den Maschinenräumen. <strong>Zeit:</strong> Nacht.</p><p>Ein krasser Kontrast zum Deck oben. Hier ist es laut, heiß und ölig. Der Chronist (Masucci) führt uns durch die „Eingeweide“ des Luxus.</p><p><strong>CHRONIST</strong> Hier unten wird die Energie erzeugt, die oben das Eis kühlt. Es ist wie mit dem Vermögen der Hortens. Oben wird gelächelt, unten wird gearbeitet. Und ganz tief im Fundament... da liegt der Schrott der Geschichte. Die Reste der Kaufhäuser, die Helmut nicht „gekauft“, sondern „übernommen“ hat.</p><p>Er deutet auf eine alte, verrostete Nähmaschine, die in einer Ecke vergessen wurde. Sie trägt das Logo der <em>Gebrüder Alsberg</em>.</p><hr><h2 id="szene-8-der-letzte-schliff-neu" tabindex="-1">Szene 8: Der letzte Schliff (NEU) <a class="header-anchor" href="#szene-8-der-letzte-schliff-neu" aria-label="Permalink to &quot;Szene 8: Der letzte Schliff (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Heidis Schlafzimmer. <strong>Zeit:</strong> Kurz vor Sonnenaufgang.</p><p>Heidi bereitet sich auf den Tag vor. Sie schminkt sich selbst. Jeder Pinselstrich ist präzise.</p><p><strong>HEIDI</strong> (zum Spiegel) Ein bisschen Weiß unter die Augen, um die Müdigkeit der Ahnen zu verbergen. Ein bisschen Rot auf die Lippen, um die Kälte der Verträge zu überdecken. Und Gold... Gold überall, um die Fragen zu blenden.</p><p>Sie tritt ans Fenster und blickt über den Wörthersee. Der See ist glatt wie ein Spiegel.</p><p><strong>HEIDI (Forts.)</strong> Heute wird ein guter Tag. Keiner wird fragen. Alle werden danken.</p><p><strong>FADE OUT.</strong></p>',60)])])}const m=n(s,[["render",a]]);export{g as __pageData,m as default};
